<script setup>
import {onMounted,ref} from 'vue'
const props=defineProps({load:{type:Function,required:true},conversations:{type:Array,default:()=>[]}})
const rows=ref([]),chatId=ref(''),kind=ref(''),days=ref(7),page=ref(1),pages=ref(1),error=ref(''),busy=ref(false)
const money=(v,c)=>v==null?'Indisponível':Number(v).toLocaleString('pt-BR',{style:'currency',currency:c,minimumFractionDigits:4,maximumFractionDigits:6})
const label=k=>({response:'Mensagem / interpretação',transcription:'Interpretação de áudio',image:'Geração de imagem',image_generation:'Geração de imagem',image_edit:'Edição de imagem',vision:'Interpretação de imagem'})[k]||k
async function refresh(reset=true){if(reset)page.value=1;busy.value=true;try{const data=await props.load({chatId:chatId.value||undefined,kind:kind.value||undefined,days:days.value,page:page.value});rows.value=data.items;pages.value=data.pages;error.value=''}catch(e){error.value='Não foi possível carregar as operações.'}finally{busy.value=false}}
onMounted(refresh)
</script>
<template><section class="usage-details"><h3>Custo por operação da IA</h3><div class="usage-filters"><label>Conversa<select v-model="chatId" @change="refresh()"><option value="">Todas</option><option v-for="chat in conversations" :key="chat.chatId" :value="chat.chatId">{{chat.name}} {{chat.phone}}</option></select></label><label>Operação<select v-model="kind" @change="refresh()"><option value="">Todas</option><option value="response">Mensagens e interpretação</option><option value="transcription">Áudios</option><option value="image">Imagens geradas</option><option value="vision">Interpretação de imagem</option></select></label><label>Período<select v-model.number="days" @change="refresh()"><option :value="1">Hoje / últimas 24h</option><option :value="7">7 dias</option><option :value="30">30 dias</option><option :value="90">90 dias</option></select></label><button type="button" @click="refresh()" :disabled="busy">Atualizar</button></div><p v-if="error">{{error}}</p><div class="usage-table"><table><thead><tr><th>Data</th><th>Conversa</th><th>Operação / modelo</th><th>Tokens / áudio</th><th>US$</th><th>R$</th></tr></thead><tbody><tr v-for="row in rows" :key="row._id"><td>{{new Date(row.createdAt).toLocaleString('pt-BR')}}</td><td>{{conversations.find(c=>String(c.chatId)===String(row.chatId))?.name||row.chatId||'Simulação'}}</td><td>{{label(row.kind)}}<small>{{row.model}}</small></td><td>{{row.totalTokens||0}} tokens<small v-if="row.audioSeconds">{{row.audioSeconds.toFixed(1)}} segundos</small></td><td>{{money(row.estimatedUsd,'USD')}}</td><td>{{money(row.estimatedBrl,'BRL')}}</td></tr></tbody></table></div><p v-if="!rows.length&&!busy">Nenhum uso neste filtro.</p><footer><button :disabled="page<=1||busy" @click="page--;refresh(false)">Anterior</button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages||busy" @click="page++;refresh(false)">Próxima</button></footer><small>Estimativas por chamada, incluindo interpretação de áudio. Ferramentas e imagens podem ter custos adicionais estimados.</small></section></template>
<style scoped>.usage-details{padding:20px;border:1px solid #42655d;border-radius:12px;margin:18px 0;background:#102c2d;color:#eafff7}.usage-filters{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.usage-filters label{display:grid;gap:6px;font-size:12px}.usage-filters select,.usage-details button{padding:9px;border:1px solid #72988a;border-radius:8px;background:#173e3d;color:#edfff8;max-width:100%}.usage-table{overflow-x:auto;margin:16px 0}table{width:100%;text-align:left;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #42655d;font-size:12px;white-space:nowrap}td small{display:block;color:#a3cbbc}footer{display:flex;justify-content:center;align-items:center;gap:12px}.usage-details>small{display:block;margin-top:12px;color:#a3cbbc}</style>
